<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useProjectStore } from '../stores/projects'
import { useTaskStore } from '../stores/tasks'
import { demoUsers } from '../data/mockData'
import type { Project, Task } from '../types'
const route = useRoute(); const router = useRouter(); const project = ref<Project>(); const tasks = ref<Task[]>([]); const loading = ref(true); const tab = ref('Board'); const projectStore = useProjectStore(); const taskStore = useTaskStore()
onMounted(async () => { project.value = await projectStore.getById(String(route.params.id)); tasks.value = (await taskStore.getAll()).filter((task) => task.projectId === route.params.id); loading.value = false })
const columns = computed(() => ['To do', 'In progress', 'Done'].map((status) => ({ status, tasks: tasks.value.filter((task) => task.status === status) })))
</script><template><div v-if="loading" class="h-80 animate-pulse rounded-panel bg-slate-200" /><div v-else-if="!project" class="rounded-panel bg-surface p-12 text-center"><h1 class="text-xl font-bold">Project not found</h1><button @click="router.push('/projects')" class="mt-4 text-primary">Back to projects</button></div><div v-else><button @click="router.push('/projects')" class="text-sm font-semibold text-primary">← Projects</button><div class="mt-5 flex flex-wrap items-start justify-between gap-4"><div><div class="flex items-center gap-3"><span :class="project.color" class="h-10 w-10 rounded-xl" /><h1 class="text-3xl font-bold">{{ project.title }}</h1></div><p class="mt-3 max-w-2xl text-sm text-secondary">{{ project.description }}</p></div><button @click="router.push(`/projects/${project.id}/tasks/new`)" class="rounded-lg bg-primary px-4 py-2.5 text-sm font-semibold text-white">+ Add task</button></div><section class="mt-7 rounded-panel border border-border bg-surface p-5"><div class="flex items-center justify-between"><span class="text-sm font-semibold">Project progress</span><span class="text-sm text-secondary">{{ project.progress }}%</span></div><div class="mt-3 h-2 rounded-full bg-surface-muted"><div class="h-full rounded-full bg-primary" :style="{ width: `${project.progress}%` }" /></div></section><div class="mt-8 flex gap-5 border-b border-border"><button v-for="item in ['Board', 'List']" :key="item" @click="tab = item" :class="tab === item ? 'border-primary text-primary' : 'border-transparent text-secondary'" class="border-b-2 pb-3 text-sm font-semibold">{{ item }}</button></div><div v-if="!tasks.length" class="mt-8 rounded-panel border border-dashed border-border bg-surface p-10 text-center"><p>No tasks yet — create one to start the project.</p></div><section v-else-if="tab === 'Board'" class="mt-6 grid gap-5 lg:grid-cols-3"><div v-for="column in columns" :key="column.status" class="rounded-panel bg-surface-muted p-4"><div class="mb-4 flex justify-between text-sm font-semibold"><span>{{ column.status }}</span><span class="text-muted">{{ column.tasks.length }}</span></div><button v-for="task in column.tasks" :key="task.id" @click="router.push(`/tasks/${task.id}`)" class="mb-3 w-full rounded-lg bg-surface p-4 text-left shadow-sm hover:shadow"><span :class="task.priority === 'High' ? 'bg-danger/10 text-danger' : task.priority === 'Medium' ? 'bg-amber-100 text-warning' : 'bg-sky-100 text-info'" class="rounded-full px-2 py-1 text-xs font-semibold">{{ task.priority }}</span><p class="mt-3 text-sm font-semibold">{{ task.title }}</p><p class="mt-3 text-xs text-muted">Due {{ task.dueDate }}</p></button></div></section><section v-else class="mt-5 overflow-hidden rounded-panel border border-border bg-surface"><button v-for="task in tasks" :key="task.id" @click="router.push(`/tasks/${task.id}`)" class="flex w-full items-center justify-between border-b border-border p-4 text-left last:border-0 hover:bg-surface-muted"><span class="font-semibold">{{ task.title }}</span><span class="text-sm text-secondary">{{ task.status }} · {{ demoUsers.find(user => user.id === task.assigneeId)?.name }}</span></button></section></div></template>
